import sys,numpy as np
sys.path.insert(0,'/opt/tools');from rcb_client import Robot
r=Robot(timeout=10);o=r.get_obs(video='none');c=o.meta['cameras']['over_shoulder_left_camera'];K=np.array(c['intrinsic_cv']);E=np.array(c['extrinsic_cv']);R=E[:,:3];C=-R.T@E[:,3]
print('C',C)
for uv in [(1070,680),(1070,650),(1000,650),(1100,690),(640,360)]:
 d=R.T@np.linalg.inv(K)@np.array([*uv,1]);
 for z in [.05,0,-.1]:
  p=C+((z-C[2])/d[2])*d;print(uv,z,p)
