import json,glob,os
for p in sorted(glob.glob('/app/runs/*')):
 if os.path.isdir(p) and os.path.exists(p+'/meta.json'):
  try:
   m=json.load(open(p+'/meta.json'))
   print(os.path.basename(p), m.get('step'),m.get('proprio',{}).get('now',[None]*16)[7:9],m.get('proprio',{}).get('now',[None]*16)[-1],m.get('done'),m.get('reason'))
  except: pass
